#[test]
fn max_message_bytes_limits_bodies_by_utf8_bytes() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    h.ok(send("abcd"));
    // two characters, five bytes
    assert_eq!(h.err(send("abé\u{20ac}")), "InvalidParameterValue");
    h.ok(send("é\u{e9}"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    // the failed sends used no message id
    assert_eq!(h.ok(send("x"))["MessageId"], "m-3");

    // the attribute is changeable, and does not touch queued messages
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    assert_eq!(h.err(send("ab")), "InvalidParameterValue");
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 10}));
    assert_eq!(r["Messages"].as_array().unwrap().len(), 3);
}

#[test]
fn max_message_bytes_attribute_rules() {
    let mut h = Harness::new();
    let create = |v: serde_json::Value| json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": v}});
    for bad in [json!(0), json!(1025), json!("5"), json!(1.5)] {
        assert_eq!(h.err(create(bad)), "InvalidParameterValue");
    }
    h.ok(create(json!(1024)));
    h.ok(create(json!(1024)));
    assert_eq!(h.err(create(json!(1))), "QueueAlreadyExists");
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1024);
    // the limit comes before the other send rules, but after the queue lookup
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "ab", "GroupId": "g"})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": "ab"})),
        "QueueDoesNotExist"
    );
}
