mod common;

use common::Harness;
use serde_json::{Value, json};

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn tags(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

fn harness() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

#[test]
fn tags_start_empty_and_are_set_replaced_and_removed() {
    let mut h = harness();
    assert_eq!(tags(&mut h), json!({}));
    assert_eq!(tag(&mut h, json!({"a": "1", "B": ""})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "1", "B": ""}));
    tag(&mut h, json!({"a": "2", "b": "3"}));
    assert_eq!(tags(&mut h), json!({"a": "2", "B": "", "b": "3"}));
    let r = h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "missing", "A"]}));
    assert_eq!(r, json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"B": "", "b": "3"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
    assert_eq!(tags(&mut h), json!({"B": "", "b": "3"}));
}

#[test]
fn key_and_value_rules() {
    let mut h = harness();
    let long_key = "k".repeat(129);
    for bad in [
        json!({"": "v"}),
        json!({"a b": "v"}),
        json!({"é": "v"}),
        json!({long_key: "v"}),
        json!({"a": 1}),
        json!({"a": null}),
        json!({"a": "x".repeat(257)}),
        // 129 two-byte characters: 258 bytes
        json!({"a": "é".repeat(129)}),
    ] {
        assert_eq!(tag(&mut h, bad.clone())["error"]["code"], "InvalidParameterValue", "{bad}");
    }
    // a bad tag next to good ones changes nothing
    assert_eq!(tag(&mut h, json!({"good": "v", "bad key": "v"}))["ok"], false);
    assert_eq!(tags(&mut h), json!({}));
    tag(&mut h, json!({"k".repeat(128): "x".repeat(256)}));
    tag(&mut h, json!({"u": "é".repeat(128)}));
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 2);

    for bad in [json!([1]), json!(["a b"]), json!([""]), json!([null]), json!("a"), json!({})] {
        let c = json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": bad});
        assert_eq!(h.err(c), "InvalidParameterValue");
    }
}

#[test]
fn check_order() {
    let mut h = harness();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "Tags": {}})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})), "InvalidParameterValue");
    // value checks come before the queue lookup, which comes before the limit
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": 1}})), "InvalidParameterValue");
    for c in ["TagQueue", "UntagQueue", "ListQueueTags"] {
        let r = h.err(json!({"Command": c, "QueueName": "nope", "Tags": {}, "TagKeys": []}));
        assert_eq!(r, "QueueDoesNotExist", "{c}");
    }
}

#[test]
fn at_most_fifty_tags() {
    let mut h = harness();
    let many = |range: std::ops::Range<u32>| {
        Value::Object(range.map(|i| (format!("k{i}"), json!("v"))).collect())
    };
    tag(&mut h, many(0..50));
    assert_eq!(tag(&mut h, many(50..51))["error"]["code"], "LimitExceeded");
    // replacing keys and an empty request still work at the limit
    assert_eq!(tag(&mut h, json!({"k0": "new"}))["ok"], true);
    assert_eq!(tag(&mut h, json!({}))["ok"], true);
    // a failed request sets nothing, even for the keys it could have fitted
    assert_eq!(tag(&mut h, json!({"k0": "newer", "extra": "v"}))["ok"], false);
    assert_eq!(tags(&mut h)["k0"], "new");
    assert!(tags(&mut h).get("extra").is_none());
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k1"]}));
    assert_eq!(tag(&mut h, json!({"extra": "v"}))["ok"], true);
    // more than 50 in one request on an empty queue
    h.ok(json!({"Command": "CreateQueue", "QueueName": "r"}));
    let r = h.run(json!({"Command": "TagQueue", "QueueName": "r", "Tags": many(0..51)}));
    assert_eq!(r["error"]["code"], "LimitExceeded");
}

#[test]
fn tags_are_not_attributes_and_follow_the_queue() {
    let mut h = harness();
    tag(&mut h, json!({"a": "1"}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(!attrs.to_string().contains("\"a\""));
    assert!(attrs["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({}));
}
